package logx_test

import (
	"errors"
	"fmt"
	"testing"

	"github.com/egdaemon/eg/internal/logx"
	"github.com/stretchr/testify/require"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestVerbose(t *testing.T) {
	t.Run("returns nil when given nil", func(t *testing.T) {
		require.Nil(t, logx.Verbose(nil))
	})

	t.Run("returns the same error when given a non-nil error", func(t *testing.T) {
		err := errors.New("boom")
		require.Same(t, err, logx.Verbose(err))
	})

	t.Run("returns wrapped error unchanged", func(t *testing.T) {
		err := fmt.Errorf("context: %w", errors.New("inner"))
		require.Same(t, err, logx.Verbose(err))
	})
}
